{"command": "cd /testbed; cat > test/tables/sfnt.test.js <<'EOF'
'use strict';

let sfnt;
let table;
let Font;
let Glyph;
let Path;

beforeAll(async () => {
    sfnt = (await import('../../src/tables/sfnt.mjs')).default;
    table = (await import('../../src/table.mjs')).default;
    Font = (await import('../../src/font.mjs')).default;
    Glyph = (await import('../../src/glyph.mjs')).default;
    Path = (await import('../../src/path.mjs')).default;
});

function makeGlyph(name, unicode, advanceWidth, leftSideBearing, box) {
    const path = new Path();
    if (box) {
        path.moveTo(box[0], box[1]);
        path.lineTo(box[2], box[1]);
        path.lineTo(box[2], box[3]);
        path.lineTo(box[0], box[3]);
        path.close();
    }
    return new Glyph({name, unicode, advanceWidth, leftSideBearing, path});
}

function createFont(glyphs, overrides) {
    return new Font(Object.assign({
        familyName: 'Test Family',
        styleName: 'Regular',
        unitsPerEm: 1000,
        ascender: 800,
        descender: -200,
        createdTimestamp: 1700000000,
        manufacturer: 'Acme Type',
        glyphs
    }, overrides || {}));
}

function createBaseGlyphs() {
    return [
        makeGlyph('.notdef', undefined, 500, 0),
        makeGlyph('space', 32, 250, 0),
        makeGlyph('A', 65, 600, 10, [10, 0, 590, 700]),
        makeGlyph('x', 120, 400, 5, [5, 0, 395, 500]),
        makeGlyph('H', 72, 650, 20, [20, 0, 630, 700])
    ];
}

function createBaseFont() {
    return createFont(createBaseGlyphs());
}

function getTableRecords(sfntTable) {
    return sfntTable.fields
        .filter((field) => typeof field.name === 'string' && field.name.endsWith(' Table Record'))
        .map((field) => field.value);
}

function getTable(sfntTable, tag) {
    const field = sfntTable.fields.find((candidate) => candidate.name === `${tag} table`);
    return field && field.value;
}

function makeTable(tag, fields) {
    return new table.Table(tag, fields);
}

describe('computeCheckSum', () => {
    test.each([
        [[], 0x00000000],
        [[0x01], 0x01000000],
        [[0x01, 0x02, 0x03], 0x01020300],
        [[0x01, 0x02, 0x03, 0x04], 0x01020304],
        [[0x01, 0x02, 0x03, 0x04, 0x05], 0x06020304],
        [[0x12, 0x34, 0x56], 0x12345600]
    ])('pads %j to a multiple of four bytes and returns an unsigned integer', (bytes, expected) => {
        expect(sfnt.computeCheckSum(bytes)).toBe(expected);
    });

    test('masks values above one byte so the result matches the bytes written to a Uint8Array', () => {
        const values = [0xAA, 0x101, 0x102];
        const truncated = Uint8Array.from(values);

        expect(sfnt.computeCheckSum(values)).toBe(0xAA010200);
        expect(sfnt.computeCheckSum(truncated)).toBe(0xAA010200);
    });

    test('accepts Uint8Array input', () => {
        expect(sfnt.computeCheckSum(new Uint8Array([0xDE, 0xAD, 0xBE, 0xEF]))).toBe(0xDEADBEEF);
    });

    test('wraps around to 32 bits instead of returning a negative or oversized number', () => {
        expect(sfnt.computeCheckSum([0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x01])).toBe(0);
        expect(sfnt.computeCheckSum([0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x02])).toBe(1);
    });
});

describe('make', () => {
    test.each([
        [1, 16, 0, 0],
        [2, 32, 1, 0],
        [3, 32, 1, 16],
        [4, 64, 2, 0],
        [5, 64, 2, 16],
        [8, 128, 3, 0],
        [9, 128, 3, 16]
    ])('calculates the binary-search header fields for %i tables', (count, searchRange, entrySelector, rangeShift) => {
        const tables = [];
        for (let i = 0; i < count; i += 1) {
            tables.push(makeTable(`t${String(i).padStart(3, '0')}`, [
                {name: 'value', type: 'BYTE', value: i}
            ]));
        }

        const result = sfnt.make(tables);

        expect(result.tableName).toBe('sfnt');
        expect(result.version).toBe('OTTO');
        expect(result.tables).toBe(tables);
        expect(result.numTables).toBe(count);
        expect(result.searchRange).toBe(searchRange);
        expect(result.entrySelector).toBe(entrySelector);
        expect(result.rangeShift).toBe(rangeShift);
        expect(getTableRecords(result)).toHaveLength(count);
    });

    test('sorts table records by tag while assigning offsets in table data order', () => {
        const zzzz = makeTable('zzzz', [
            {name: 'half', type: 'USHORT', value: 0x1234},
            {name: 'byte', type: 'BYTE', value: 0x56}
        ]);
        const mooo = makeTable('mooo', [
            {name: 'byte', type: 'BYTE', value: 0xAB}
        ]);
        const abcd = makeTable('abcd', [
            {name: 'word', type: 'ULONG', value: 0x01020304}
        ]);

        const result = sfnt.make([zzzz, mooo, abcd]);
        const records = getTableRecords(result);

        expect(records.map((record) => record.tag)).toEqual(['abcd', 'mooo', 'zzzz']);
        expect(records.map((record) => record.offset)).toEqual([68, 64, 60]);
        expect(records.map((record) => record.length)).toEqual([4, 1, 3]);
        expect(records.map((record) => record.checkSum)).toEqual([
            0x01020304,
            0xAB000000,
            0x12345600
        ]);
        expect(result.sizeOf()).toBe(72);
    });

    test('writes a consistent sfnt header, table directory, padding, and table data', () => {
        const zzzz = makeTable('zzzz', [
            {name: 'half', type: 'USHORT', value: 0x1234},
            {name: 'byte', type: 'BYTE', value: 0x56}
        ]);
        const mooo = makeTable('mooo', [
            {name: 'byte', type: 'BYTE', value: 0xAB}
        ]);
        const abcd = makeTable('abcd', [
            {name: 'word', type: 'ULONG', value: 0x01020304}
        ]);

        const bytes = sfnt.make([zzzz, mooo, abcd]).encode();

        expect(bytes).toHaveLength(72);
        expect(bytes.slice(0, 12)).toEqual([
            0x4F, 0x54, 0x54, 0x4F,
            0x00, 0x03,
            0x00, 0x20,
            0x00, 0x01,
            0x00, 0x10
        ]);

        expect(bytes.slice(12, 28)).toEqual([
            0x61, 0x62, 0x63, 0x64,
            0x01, 0x02, 0x03, 0x04,
            0x00, 0x00, 0x00, 0x44,
            0x00, 0x00, 0x00, 0x04
        ]);
        expect(bytes.slice(28, 44)).toEqual([
