    table = (await import('../../src/table.mjs')).default;
    Font = (await import('../../src/font.mjs')).default;
    Glyph = (await import('../../src/glyph.mjs')).default;
    Path = (await import('../../src/path.mjs')).default;
});

function makeGlyph(name, unicode, advanceWidth, leftSideBearing, box) {
    const path = new Path();
    if (box) {
        path.moveTo(box[0], box[1]);
        path.lineTo(box[2], box[1]);
        path.lineTo(box[2], box[3]);
        path.lineTo(box[0], box[3]);
        path.close();
    }
    return new Glyph({name, unicode, advanceWidth, leftSideBearing, path});
}

function createFont(glyphs, overrides) {
    return new Font(Object.assign({
        familyName: 'Test Family',
        styleName: 'Regular',
        unitsPerEm: 1000,
        ascender: 800,
        descender: -200,
        createdTimestamp: 1700000000,
        manufacturer: 'Acme Type',
        glyphs
    }, overrides || {}));
}

function createBaseGlyphs() {
    return [
        makeGlyph('.notdef', undefined, 500, 0),
        makeGlyph('space', 32, 250, 0),
        makeGlyph('A', 65, 600, 10, [10, 0, 590, 700]),
        makeGlyph('x', 120, 400, 5, [5, 0, 395, 500]),
        makeGlyph('H', 72, 650, 20, [20, 0, 630, 700])
    ];
}

function createBaseFont() {
    return createFont(createBaseGlyphs());
}

function getTableRecords(sfntTable) {
    return sfntTable.fields
        .filter((field) => typeof field.name === 'string' && field.name.endsWith(' Table Record'))
        .map((field) => field.value);
}

function getTable(sfntTable, tag) {
    const field = sfntTable.fields.find((candidate) => candidate.name === `${tag} table`);
    return field && field.value;
}

function makeTable(tag, fields) {
    return new table.Table(tag, fields);
}

describe('computeCheckSum', () => {
    test.each([
        [[], 0x00000000],
        [[0x01], 0x01000000],
        [[0x01, 0x02, 0x03], 0x01020300],
        [[0x01, 0x02, 0x03, 0x04], 0x01020304],
        [[0x01, 0x02, 0x03, 0x04, 0x05], 0x06020304],
        [[0x12, 0x34, 0x56], 0x12345600]
    ])('pads %j to a multiple of four bytes and returns an unsigned integer', (bytes, expected) => {
        expect(sfnt.computeCheckSum(bytes)).toBe(expected);
    });

    test('masks values above one byte so the result matches the bytes written to a Uint8Array', () => {
        const values = [0xAA, 0x101, 0x102];
        const truncated = Uint8Array.from(values);

        expect(sfnt.computeCheckSum(values)).toBe(0xAA010200);
        expect(sfnt.computeCheckSum(truncated)).toBe(0xAA010200);
    });

    test('accepts Uint8Array input', () => {
        expect(sfnt.computeCheckSum(new Uint8Array([0xDE, 0xAD, 0xBE, 0xEF]))).toBe(0xDEADBEEF);
    });

    test('wraps around to 32 bits instead of returning a negative or oversized number', () => {
        expect(sfnt.computeCheckSum([0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x01])).toBe(0);
        expect(sfnt.computeCheckSum([0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x02])).toBe(1);
    });
});

describe('make', () => {
    test.each([
        [1, 16, 0, 0],
        [2, 32, 1, 0],
        [3, 32, 1, 16],
        [4, 64, 2, 0],
        [5, 64, 2, 16],
        [8, 128, 3, 0],
        [9, 128, 3, 16]
    ])('calculates the binary-search header fields for %i tables', (count, searchRange, entrySelector, rangeShift) => {
        const tables = [];
        for (let i = 0; i < count; i += 1) {
            tables.push(makeTable(`t${String(i).padStart(3, '0')}`, [
                {name: 'value', type: 'BYTE', value: i}
            ]));
        }

        const result = sfnt.make(tables);

        expect(result.tableName).toBe('sfnt');
        expect(result.version).toBe('OTTO');
        expect(result.tables).toBe(tables);
        expect(result.numTables).toBe(count);
        expect(result.searchRange).toBe(searchRange);
        expect(result.entrySelector).toBe(entrySelector);
        expect(result.rangeShift).toBe(rangeShift);
        expect(getTableRecords(result)).toHaveLength(count);
    });

    test('sorts table records by tag while assigning offsets in table data order', () => {
        const zzzz = makeTable('zzzz', [
            {name: 'half', type: 'USHORT', value: 0x1234},
            {name: 'byte', type: 'BYTE', value: 0x56}
        ]);
        const mooo = makeTable('mooo', [
            {name: 'byte', type: 'BYTE', value: 0xAB}
        ]);
        const abcd = makeTable('abcd', [
            {name: 'word', type: 'ULONG', value: 0x01020304}
        ]);

        const result = sfnt.make([zzzz, mooo, abcd]);
        const records = getTableRecords(result);

        expect(records.map((record) => record.tag)).toEqual(['abcd', 'mooo', 'zzzz']);
        expect(records.map((record) => record.offset)).toEqual([68, 64, 60]);
        expect(records.map((record) => record.length)).toEqual([4, 1, 3]);
        expect(records.map((record) => record.checkSum)).toEqual([
            0x01020304,
            0xAB000000,
            0x12345600
        ]);
        expect(result.sizeOf()).toBe(72);
    });

    test('writes a consistent sfnt header, table directory, padding, and table data', () => {
        const zzzz = makeTable('zzzz', [
            {name: 'half', type: 'USHORT', value: 0x1234},
            {name: 'byte', type: 'BYTE', value: 0x56}
        ]);
        const mooo = makeTable('mooo', [
            {name: 'byte', type: 'BYTE', value: 0xAB}
        ]);
        const abcd = makeTable('abcd', [
            {name: 'word', type: 'ULONG', value: 0x01020304}
        ]);

        const bytes = sfnt.make([zzzz, mooo, abcd]).encode();

        expect(bytes).toHaveLength(72);
        expect(bytes.slice(0, 12)).toEqual([
            0x4F, 0x54, 0x54, 0x4F,
            0x00, 0x03,
            0x00, 0x20,
            0x00, 0x01,
            0x00, 0x10
        ]);

        expect(bytes.slice(12, 28)).toEqual([
            0x61, 0x62, 0x63, 0x64,
            0x01, 0x02, 0x03, 0x04,
            0x00, 0x00, 0x00, 0x44,
            0x00, 0x00, 0x00, 0x04
        ]);
        expect(bytes.slice(28, 44)).toEqual([
            0x6D, 0x6F, 0x6F, 0x6F,
            0xAB, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x40,
            0x00, 0x00, 0x00, 0x01
        ]);
        expect(bytes.slice(44, 60)).toEqual([
            0x7A, 0x7A, 0x7A, 0x7A,
            0x12, 0x34, 0x56, 0x00,
            0x00, 0x00, 0x00, 0x3C,
            0x00, 0x00, 0x00, 0x03
        ]);

        expect(bytes.slice(60, 72)).toEqual([
            0x12, 0x34, 0x56, 0x00,
            0xAB, 0x00, 0x00, 0x00,
            0x01, 0x02, 0x03, 0x04
        ]);
    });

    test.each(['abc', 'abcde', ''])('rejects table tag %j because it is not exactly four characters', (tag) => {
        const badTable = makeTable(tag, [{name: 'value', type: 'BYTE', value: 1}]);

        expect(() => sfnt.make([badTable])).toThrow(/is invalid\.$/);
    });
});

describe('fontToTable', () => {
    test('wraps the generated font tables in a valid, checksummed OTTO sfnt container', () => {
        const sfntTable = sfnt.fontToTable(createBaseFont());
        const records = getTableRecords(sfntTable);
        const tags = records.map((record) => record.tag);

        expect(sfntTable.tableName).toBe('sfnt');
        expect(sfntTable.version).toBe('OTTO');
        expect(sfntTable.numTables).toBe(records.length);
        expect(tags).toEqual([...tags].sort());
        expect(tags).toEqual(expect.arrayContaining([
            'CFF ', 'OS/2', 'cmap', 'head', 'hhea', 'hmtx',
            'ltag', 'maxp', 'name', 'post'
        ]));
        expect(tags).not.toContain('gasp');
        expect(tags).not.toContain('meta');

        const directoryEnd = 12 + 16 * records.length;
        records.forEach((record) => {
            expect(record.offset % 4).toBe(0);
            expect(record.offset).toBeGreaterThanOrEqual(directoryEnd);
            expect(record.length).toBe(getTable(sfntTable, record.tag).sizeOf());
        });
        expect(new Set(records.map((record) => record.offset)).size).toBe(records.length);

        records.forEach((record) => {
            const tableData = getTable(sfntTable, record.tag);
            if (record.tag === 'head') {
                const headTable = tableData;
                const adjustment = headTable.checkSumAdjustment;
                let expected;
                headTable.checkSumAdjustment = 0;
                try {
                    expected = sfnt.computeCheckSum(headTable.encode());
                } finally {
                    headTable.checkSumAdjustment = adjustment;
                }
                expect(record.checkSum).toBe(expected);
            } else {
                expect(record.checkSum).toBe(sfnt.computeCheckSum(tableData.encode()));
            }
        });

        expect(sfntTable.sizeOf()).toBe(sfntTable.encode().length);
        expect(sfnt.computeCheckSum(sfntTable.encode())).toBe(0xB1B0AFBA);
    });

    test('derives head, hhea, maxp, and hmtx values from the glyph set', () => {
        const sfntTable = sfnt.fontToTable(createBaseFont());
        const headTable = getTable(sfntTable, 'head');
        const hheaTable = getTable(sfntTable, 'hhea');
        const maxpTable = getTable(sfntTable, 'maxp');
        const hmtxTable = getTable(sfntTable, 'hmtx');

        expect(headTable).toMatchObject({
            unitsPerEm: 1000,
            xMin: 0,
            yMin: 0,
            xMax: 630,
            yMax: 700,
            flags: 3,
            lowestRecPPEM: 3,
            macStyle: 0,
            created: 1700000000 + 2082844800
        });
        expect(headTable.checkSumAdjustment).toBeGreaterThan(0);

        expect(hheaTable).toMatchObject({
            ascender: 800,
            descender: -200,
            advanceWidthMax: 650,
            minLeftSideBearing: 0,
            minRightSideBearing: 0,
            xMaxExtent: 650,
            numberOfHMetrics: 5
        });
        expect(maxpTable.numGlyphs).toBe(5);

        expect(hmtxTable.sizeOf()).toBe(20);
        expect(hmtxTable.fields
            .filter((field) => field.name.startsWith('advanceWidth_'))
            .map((field) => hmtxTable[field.name])).toEqual([500, 250, 600, 400, 650]);
        expect(hmtxTable.fields
            .filter((field) => field.name.startsWith('leftSideBearing_'))
            .map((field) => hmtxTable[field.name])).toEqual([0, 0, 10, 5, 20]);
    });

    test('reflects character coverage and glyph metrics in the OS/2 table', () => {
        const os2Table = getTable(sfnt.fontToTable(createBaseFont()), 'OS/2');

        expect(os2Table).toMatchObject({
            xAvgCharWidth: 475,
            usFirstCharIndex: 32,
            usLastCharIndex: 120,
            ulUnicodeRange1: 1,
            ulUnicodeRange2: 0,
            sTypoAscender: 800,
            sTypoDescender: -200,
            sTypoLineGap: 0,
            usWinAscent: 700,
            usWinDescent: 0,
            ulCodePageRange1: 1,
            sxHeight: 500,
            sCapHeight: 700,
            usDefaultChar: 32,
            usBreakChar: 32
        });
    });

    test('uses fallback OS/2 metrics and no default character when preferred glyphs are absent', () => {
        const font = createFont([
            makeGlyph('.notdef', undefined, 500, 0),
            makeGlyph('z', 122, 500, 0, [0, 0, 300, 400])
        ], {
            ascender: 900,
            descender: -300
        });

        const sfntTable = sfnt.fontToTable(font);
        const os2Table = getTable(sfntTable, 'OS/2');
        const headTable = getTable(sfntTable, 'head');

        expect(os2Table).toMatchObject({
            sxHeight: 450,
            sCapHeight: 400,
            usDefaultChar: 0,
            usBreakChar: 0,
            usFirstCharIndex: 122,
            usLastCharIndex: 122,
            usWinAscent: 400,
            usWinDescent: 0
        });
        expect(headTable).toMatchObject({xMin: 0, yMin: 0, xMax: 300, yMax: 400});
        expect(sfnt.computeCheckSum(sfntTable.encode())).toBe(0xB1B0AFBA);
    });

    test.each([
        [{weightClass: 700}, 1],
        [{italicAngle: -15}, 2],
        [{weightClass: 600, italicAngle: -0.5}, 3],
        [{weightClass: 599, italicAngle: 0}, 0]
    ])('sets head.macStyle from font weight and italic angle (%j)', (overrides, expectedMacStyle) => {
        const font = createFont(createBaseGlyphs(), overrides);
        const headTable = getTable(sfnt.fontToTable(font), 'head');

        expect(headTable.macStyle).toBe(expectedMacStyle);
    });

    test('lets font.tables.os2 values override computed OS/2 defaults', () => {
        const font = createBaseFont();
        font.tables.os2.usWeightClass = 900;
        font.tables.os2.achVendID = 'TEST';
        font.tables.os2.fsSelection = 0x20;
        font.tables.os2.sTypoAscender = 777;

        const os2Table = getTable(sfnt.fontToTable(font), 'OS/2');

        expect(os2Table).toMatchObject({
            usWeightClass: 900,
            achVendID: 'TEST',
            fsSelection: 0x20,
            sTypoAscender: 777,
            sTypoDescender: -200,
            usWinAscent: 700
        });
    });

    test('includes optional font tables and font metadata when they are present', () => {
        const font = createBaseFont();
        font.tables.gasp = {
            numRanges: 2,
            gaspRanges: [
                {rangeMaxPPEM: 8, rangeGaspBehavior: 1},
                {rangeMaxPPEM: 65535, rangeGaspBehavior: 3}
            ]
        };
        font.metas = {dlng: 'Latn', slng: 'Latn'};

        const sfntTable = sfnt.fontToTable(font);
        const tags = getTableRecords(sfntTable).map((record) => record.tag);
        const gaspTable = getTable(sfntTable, 'gasp');
        const metaTable = getTable(sfntTable, 'meta');

        expect(tags).toContain('gasp');
        expect(tags).toContain('meta');
        expect(gaspTable.numRanges).toBe(2);
        expect(gaspTable.fields.slice(2).map((field) => gaspTable[field.name]))
            .toEqual([8, 1, 65535, 3]);
        expect(metaTable.numTags).toBe(2);
        expect(metaTable.stringPool).toBe('LatnLatn');
        expect(sfnt.computeCheckSum(sfntTable.encode())).toBe(0xB1B0AFBA);
    });

    test('throws a descriptive error when a glyph advance width is not numeric', () => {
        const font = createFont([
            makeGlyph('.notdef', undefined, 500, 0),
            makeGlyph('space', 32, 250, 0),
            makeGlyph('A', 65, 'wide', 10, [10, 0, 590, 700])
        ]);

        expect(() => sfnt.fontToTable(font)).toThrow('Glyph A (2): advanceWidth is not a number.');
    });
});
