function makeGlyph(name, unicode, advanceWidth, leftSideBearing, box) {
    const path = new Path();
    if (box) {
        path.moveTo(box[0], box[1]);
        path.lineTo(box[2], box[1]);
        path.lineTo(box[2], box[3]);
        path.lineTo(box[0], box[3]);
        path.close();
    }
    return new Glyph({name, unicode, advanceWidth, leftSideBearing, path});
}

function createFont(glyphs, overrides) {
    return new Font(Object.assign({
        familyName: 'Test Family',
        styleName: 'Regular',
        unitsPerEm: 1000,
        ascender: 800,
        descender: -200,
        createdTimestamp: 1700000000,
        manufacturer: 'Acme Type',
        glyphs
    }, overrides || {}));
}

function createBaseGlyphs() {
    return [
        makeGlyph('.notdef', undefined, 500, 0),
        makeGlyph('space', 32, 250, 0),
        makeGlyph('A', 65, 600, 10, [10, 0, 590, 700]),
        makeGlyph('x', 120, 400, 5, [5, 0, 395, 500]),
        makeGlyph('H', 72, 650, 20, [20, 0, 630, 700])
    ];
}

