        expect(normalized[1]).toBeCloseTo(0.5, 10);
    });

    test('normalizes below-axis values into the -1..0 range', () => {
        const processor = new VariationProcessor(makeFont({ axes }));

        const normalized = processor.getNormalizedCoords({ wght: 250 });

        expect(normalized[0]).toBeCloseTo(-0.5, 10);
        expect(normalized[1]).toBeCloseTo(0, 10);
    });

    test('returns -1 and 1 at the axis extremes', () => {
        const processor = new VariationProcessor(makeFont({ axes }));

        expect(processor.getNormalizedCoords({ wght: 100, wdth: 50 })[0]).toBeCloseTo(-1, 10);
        expect(processor.getNormalizedCoords({ wght: 900, wdth: 200 })[1]).toBeCloseTo(1, 10);
    });

