describe('getNormalizedCoords', () => {
    const axes = [
        axis('wght', 100, 400, 900),
        axis('wdth', 50, 100, 200),
    ];

    test('maps coordinates below and above the default to -1..1', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const normalized = processor.getNormalizedCoords({ wght: 150, wdth: 150 });
        expect(normalized).toHaveLength(2);
        expect(normalized[0]).toBeCloseTo(-0.5, 6);
        expect(normalized[1]).toBeCloseTo(0.5, 6);
    });

    test('returns zero for default, -1 at min and 1 at max', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        expect(processor.getNormalizedCoords({ wght: 400, wdth: 100 })).toEqual([
            expect.closeTo(0, 6), expect.closeTo(0, 6),
        ]);
        expect(processor.getNormalizedCoords({ wght: 100, wdth: 50 })).toEqual([
            expect.closeTo(-1, 6), expect.closeTo(-1, 6),
        ]);
        expect(processor.getNormalizedCoords({ wght: 900, wdth: 200 })).toEqual([
            expect.closeTo(1, 6), expect.closeTo(1, 6),
        ]);
    });

    test('uses axis defaults when a coordinate is missing', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const normalized = processor.getNormalizedCoords({ wght: 650 });
        expect(normalized[0]).toBeCloseTo(0.5, 6);
        expect(normalized[1]).toBeCloseTo(0, 6);
    });

    test('normalizes short tags before looking up axes', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const normalized = processor.getNormalizedCoords({ wg: 650 });
        expect(normalized[0]).toBeCloseTo(0.5, 6);
    });

    test('falls back to font.variation.get() when no coordinates are passed', () => {
        const font = makeFont({ axes, coords: { wght: 650, wdth: 100 } });
        const processor = new VariationProcessor(font);
        expect(processor.getNormalizedCoords()[0]).toBeCloseTo(0.5, 6);
    });

    test('applies avar segment interpolation', () => {
        const avar = {
            axisSegmentMaps: [{
                axisValueMaps: [
                    { fromCoordinate: -1, toCoordinate: -1 },
                    { fromCoordinate: -0.5, toCoordinate: -0.25 },
                    { fromCoordinate: 0, toCoordinate: 0 },
                    { fromCoordinate: 1, toCoordinate: 1 },
                ],
            }],
        };
        const processor = new VariationProcessor(makeFont({ axes: [axis('wght', -100, 0, 100)], avar }));
        const normalized = processor.getNormalizedCoords({ wght: -75 });
        expect(normalized[0]).toBeCloseTo(-0.375, 6);
    });

    test('does not apply avar mapping when the value equals a map endpoint', () => {
        const avar = {
            axisSegmentMaps: [{
                axisValueMaps: [
                    { fromCoordinate: -1, toCoordinate: -1 },
                    { fromCoordinate: 0, toCoordinate: 0 },
                    { fromCoordinate: 1, toCoordinate: 1 },
                ],
            }],
        };
        const processor = new VariationProcessor(makeFont({ axes: [axis('wght')], avar }));
        expect(processor.getNormalizedCoords({ wght: 1 })[0]).toBeCloseTo(1, 6);
        expect(processor.getNormalizedCoords({ wght: 0 })[0]).toBeCloseTo(0, 6);
    });
});

