let VariationProcessor;
let Glyph;

async function loadTarget() {
    try {
        const mod = await import('../src/variationprocessor.mjs');
        const glyphMod = await import('../src/glyph.mjs');
        return { VariationProcessor: mod.VariationProcessor, Glyph: glyphMod.default };
    } catch (error) {
        const requireFn = eval('typeof require !== "undefined" ? require : undefined');
        if (!requireFn) throw error;
        const path = requireFn('path');
        const esbuild = requireFn('esbuild');
        const Module = requireFn('module');
        const bundleModule = (relative) => {
            const entry = path.resolve(__dirname, relative);
            const build = esbuild.buildSync({
                entryPoints: [entry], bundle: true, format: 'cjs',
                platform: 'node', write: false, define: { DEBUG: 'false' },
            });
            const loaded = new Module(entry, module);
            loaded.filename = entry;
            loaded.paths = Module._nodeModulePaths(path.dirname(entry));
            loaded._compile(build.outputFiles[0].text, entry);
            return loaded.exports;
        };
        const vp = bundleModule('../src/variationprocessor.mjs');
        const glyphExports = bundleModule('../src/glyph.mjs');
        return { VariationProcessor: vp.VariationProcessor, Glyph: glyphExports.default };
    }
}

beforeAll(async () => {
    ({ VariationProcessor, Glyph } = await loadTarget());
});

function makeFont({ axes = [], avar, gvar, hvar, cvar, cvt, coords = {}, glyphs = {} } = {}) {
    const tables = { fvar: { axes } };
    if (avar !== undefined) tables.avar = avar;
    if (gvar !== undefined) tables.gvar = gvar;
    if (hvar !== undefined) tables.hvar = hvar;
    if (cvar !== undefined) tables.cvar = cvar;
    if (cvt !== undefined) tables.cvt = cvt;
    return {
        tables,
        variation: { get: () => Object.assign({}, coords) },
        glyphs: { get: (index) => glyphs[index] },
        defaultRenderOptions: { variation: Object.assign({}, coords) },
    };
}

const axis = (tag, minValue = -1, defaultValue = 0, maxValue = 1) => ({ tag, minValue, defaultValue, maxValue });
const point = (x, y, onCurve = true, lastPointOfContour = false) => ({ x, y, onCurve, lastPointOfContour });

function region(axes) {
    return { regionAxes: axes.map(([startCoord, peakCoord, endCoord]) => ({ startCoord, peakCoord, endCoord })) };
}

function itemStore(regions, deltaSets) {
    return {
        itemVariationSubtables: [{
            regionIndexes: regions.map((_, i) => i),
            deltaSets,
        }],
        variationRegions: regions,
    };
}

